param($TargetDrive = 'C:', $ThresholdGB = 10)

# DataVault Backup - Pre-Scan Inventory Script
$LogPath = 'C:\ProgramData\DataVault\Logs\inventory_scan.log'
$ReportPath = 'C:\ProgramData\DataVault\Temp\large_files.csv'

function Write-Log($Message) {
    $TS = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'
    "[$TS] $Message" | Out-File -FilePath $LogPath -Append
}

try {
    Write-Log 'Starting storage inventory scan...'
    $LargeFiles = Get-ChildItem -Path $TargetDrive -Recurse -File -ErrorAction SilentlyContinue | 
                  Where-Object { $_.Length -gt ($ThresholdGB * 1GB) } | 
                  Select-Object Name, @{Name='SizeGB';Expression={$_.Length / 1GB}}, FullName

    $LargeFiles | Export-Csv -Path $ReportPath -NoTypeInformation
    Write-Log "Scan complete. Found $($LargeFiles.Count) files exceeding threshold."
}
catch {
    Write-Log "Error during scan: $($_.Exception.Message)"
}
